from pathlib import Path
import html,re,difflib,markdown,json
from PIL import Image,ImageDraw,ImageFont
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[3]
def font(size,bold=False):return ImageFont.truetype('C:/Windows/Fonts/'+('segoeuib.ttf' if bold else 'segoeui.ttf'),size)
fig=Image.new('RGB',(1740,795),'#eeeae2');draw=ImageDraw.Draw(fig)
draw.text((60,25),'THE PATTERN AND ITS SUPPORT',font=font(32,True),fill='#252622')
draw.text((60,74),'The image changes. The wall can change too.',font=font(24),fill='#676258')
for i,(name,title,caption) in enumerate([('changed-pattern','01 / A tile turns','The sheet still stops the body.'),('opened-wall','02 / The wall turns','The same image travels with an opening.')]):
 im=Image.open(OUT/(name+'.png')).convert('RGB');im.thumbnail((780,520),Image.Resampling.LANCZOS);x=60+i*840
 fig.paste(im,(x,130));draw.text((x,673),title,font=font(28,True),fill='#252622');draw.text((x,716),caption,font=font(24),fill='#676258')
fig.save(OUT/'two-turns.png')
def render(text,prefix):
 text=re.sub(r'<!--\s*@[^>]*-->','',text)
 return markdown.markdown(text,extensions=['extra','sane_lists']).replace('id="fn','id="'+prefix+'-fn').replace('href="#fn','href="#'+prefix+'-fn')
def photo(name,caption):return '<figure><a href="'+name+'.png"><img loading="lazy" src="'+name+'.png" alt="'+html.escape(caption,quote=True)+'"></a><figcaption>'+caption+'</figcaption></figure>'
before=(OUT/'Tutorial_Tiling_Walls.before.md').read_text(encoding='utf-8');after=(OUT/'Tutorial_Tiling_Walls.after.md').read_text(encoding='utf-8');assert after==(ROOT/'commons/maps/Tutorial_Tiling_Walls/final.md').read_text(encoding='utf-8')
a,b=before.split('\n\n'),after.split('\n\n');pairs=[]
for i,(tag,x,y,u,v) in enumerate(difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes()):
 if tag=='equal':continue
 pairs.append('<div class="pair"><div><h3>Before</h3>'+(render('\n\n'.join(a[x:y]),'old'+str(i)) or '<p>New illustration.</p>')+'</div><div><h3>Now</h3>'+render('\n\n'.join(b[u:v]),'new'+str(i))+'</div></div>')
css=re.search(r'<style>(.*?)</style>',(OUT.parent/'2026-09-23-array-molnar-volume/index.html').read_text(encoding='utf-8'),re.S)[1]
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>The pattern and its support — tiling walls</title><style>'+css+'</style></head><body><main>'
page+='''<div class="eyebrow">Ada Research · Arrays and regularity · 23 September 2026</div><h1>The pattern and its support.</h1><p class="intro">A thin sheet was enough<br>to keep us inside.</p><p class="status">Applied to <strong>Tutorial_Tiling_Walls/final.md</strong>. The chapter keeps its encounter with the museum’s thin enclosure. One sentence is clearer, and the working wall now supplies its book illustration.</p><nav><a href="#encounter">Two turns</a><a href="#outside">The other side</a><a href="#comparison">Text changes</a><a href="#reading">Read the hall</a><a href="#evidence">Evidence</a><a href="/compose/sources?map=Tutorial_Tiling_Walls&amp;doc=final">Read and comment</a></nav>'''
page+='<section id="encounter"><h2>What did the turn change?</h2>'+photo('two-turns','Two native views from the same position. Both show the changed tile. Turning the sheet moves its pattern and its collision together, opening a passage.')+'<p>The six tiling studies have stood up. Near the far end, one of their images has reached the museum’s own boundary. The familiar quarter turn now gives us a way to leave the forward route.</p><details><summary>The wall studies and the image change</summary>'+photo('wall-fields','The same six monochrome image rules, now facing the body.')+'<div class="photos">'+photo('closed-pattern','Before EXCEPTION: the repeated motif on the closed sheet.')+photo('changed-pattern','After EXCEPTION: one tile turns; the wall remains closed.')+'</div></details></section>'
page+='<section id="outside"><h2>Even this outside was made</h2><div class="photos">'+photo('outside-return','Looking back from the position reached by the walking body, at a staged eye height of 1.65 metres.')+photo('plain-reverse','A selected view from the landing: the plain reverse, thin edge and rail. Beyond the landing, there is no floor to continue this route.')+'</div><p>The passage already carries your idea that a thin enclosure follows our forward walk. It stays intact. The images let the reader inspect the sheet and the little outside that the text discovers.</p></section>'
page+='<section id="comparison"><h2>A small clarification</h2><p>“The image has changed; the wall still holds you on this side.” This keeps the bodily address while making clear what stops the visitor. The rest of the prose, the code, both artifact encounters and the onward link to time remain.</p><details><summary>Original and current passages</summary>'+''.join(pairs)+'</details><p><a href="Tutorial_Tiling_Walls.diff">Exact manuscript diff</a> · <a href="source-changes.diff">Companion notes and encounter metadata</a></p></section>'
page+='<section id="reading"><article class="reading"><h2>What changes when a floor stands up?</h2>'+render(after,'reading')+'</article></section>'
page+='''<section id="evidence" class="evidence"><h2>What was checked</h2><p>25 focused checks pass in the isolated production museum. Supplied pointer events change the existing image and wall controls. The normal museum controller receives supplied key input: the closed wall stops the body; after retreat and opening, it can walk onto the landing and return. The wall refuses to close while the landing is occupied and closes after the return.</p><p>The figure uses unchanged native renders with labels, layout and resizing. The pattern texture remains the same through the wall’s quarter turn. Selected cameras and supplied input do not establish physical reach, headset comfort or learner experience.</p><p>The existing artifacts, placement, controls and sequence are preserved. Earlier guard and geometry checks remain in the <a href="../2026-09-20-wall-exception/SUMMARY.md">original wall encounter record</a>. This pass does not repeat the six-rule pixel checks completed in the <a href="../2026-09-23-tiling-underfoot/index.html">preceding floor hall</a>.</p><p><a href="report.json">Runtime checks</a> · <a href="source_manifest.json">Capture inputs</a> · <a href="verification.json">Publication checks</a> · <a href="SUMMARY.md">Findings and decisions</a></p></section><footer>Next: Tutorial_Disco. An address stays in place while the value it shows changes with time.</footer></main></body></html>'''
(OUT/'index.html').write_text(page,encoding='utf-8');print('Built shared wall illustration and review page.')
